import{_ as r}from"./chunks/uavcan_wiring.0Ml-olhd.js";import{_ as o,o as t,c as n,al as i,j as e,a as l}from"./chunks/framework.7vp1BMOE.js";const f=JSON.parse('{"title":"CAN (DroneCAN & Cyphal)","description":"","frontmatter":{},"headers":[],"relativePath":"uk/can/index.md","filePath":"uk/can/index.md"}'),s={name:"uk/can/index.md"};function h(p,a,c,d,u,C){return t(),n("div",null,[...a[0]||(a[0]=[i('<h1 id="can-dronecan-cyphal" tabindex="-1">CAN (DroneCAN &amp; Cyphal) <a class="header-anchor" href="#can-dronecan-cyphal" aria-label="Permalink to &quot;CAN (DroneCAN &amp; Cyphal)&quot;">​</a></h1><p><a href="https://en.wikipedia.org/wiki/CAN_bus" target="_blank" rel="noreferrer">Controller Area Network (CAN)</a> is a robust wired network that allows drone components such as flight controller, ESCs, sensors, and other peripherals, to communicate with each other.</p><p>It is particularly recommended on larger vehicles.</p><h2 id="загальнии-огляд" tabindex="-1">Загальний огляд <a class="header-anchor" href="#загальнии-огляд" aria-label="Permalink to &quot;Загальний огляд&quot;">​</a></h2><p>CAN it is designed to be democratic and uses differential signaling. For this reason it is very robust even over longer cable lengths (on large vehicles), and avoids a single point of failure. CAN також дозволяє отримання зворотного зв&#39;язку від периферійних пристроїв та зручне оновлення прошивки через шину.</p><p>PX4 has the ability to track and log detailed information from CAN devices, including firmware versions, hardware versions, and serial numbers. This enables unique identification and lifecycle tracking of hardware connected to the flight controller. See <a href="./../debug/asset_tracking">Asset Tracking</a> for more information.</p><p>PX4 підтримує два програмні протоколи для взаємодії з пристроями CAN:</p><ul><li><a href="./../dronecan/README">DroneCAN</a>: PX4 рекомендує це для більшості типових налаштувань. Воно має гарну підтримку в PX4, є вже досить зрілим продуктом з широкою підтримкою периферійних пристроїв та багаторічними тестами.</li><li><a href="https://opencyphal.org" target="_blank" rel="noreferrer">Cyphal</a>: PX4 support is a &quot;work in progress&quot;. Cyphal - набагато новіший протокол, який надає більше гнучкості та конфігураційних можливостей, особливо на більших і складніших транспортних засобах. Він ще не отримав значного впровадження.</li></ul><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Обидва DroneCAN і Cyphal походять з раніше проекту під назвою UAVCAN. У 2022 році проект розділився на дві частини: оригінальна версія UAVCAN (UAVCAN v0) була перейменована в DroneCAN, а нова версія UAVCAN v1 отримала назву Cyphal. Відмінності між цими двома протоколами описані в <a href="https://forum.opencyphal.org/t/cyphal-vs-dronecan/1814" target="_blank" rel="noreferrer">Cyphal vs. DroneCAN</a>.</p></div><p>У PX4 немає підтримки інших програмних протоколів CAN для безпілотних літальних апаратів, таких як KDECAN (на момент написання).</p><h2 id="підключення" tabindex="-1">Підключення <a class="header-anchor" href="#підключення" aria-label="Permalink to &quot;Підключення&quot;">​</a></h2><p>Проводка для мереж CAN однакова як для DroneCAN, так і для Cyphal/CAN (фактично, для всіх мереж CAN).</p><p>Devices within a network are connected in a <em>daisy-chain</em> in any order (this differs from UARTs peripherals, where you attach just one component per port).</p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>Don&#39;t connect each CAN peripheral to a separate CAN port! Unlike UARTs, CAN peripherals are designed to be daisy chained, with additional ports such as <code>CAN2</code> used for <a href="#redundancy">redundancy</a>.</p></div><p>На обох кінцях ланцюга між двома лініями передачі даних слід під’єднати термінальний резистор 120 Ом. Польотні контролери та деякі модулі GNSS мають вбудовані резистори завершення для зручності, тому їх слід розміщувати на протилежних кінцях ланцюга. В іншому випадку, ви можете використовувати резистор завершення, наприклад, <a href="https://shop.zubax.com/products/uavcan-micro-termination-plug?variant=6007985111069" target="_blank" rel="noreferrer">цей від Zubax Robotics</a>, або припаяти його самостійно, якщо у вас є доступ до затискача JST-GH.</p><p>Наступна діаграма показує приклад шини CAN, що з&#39;єднує автопілот з 4 контролерами ESC CAN та GNSS. It includes a redundant bus connected to <code>CAN 2</code>.</p><p><img src="'+r+'" alt="CAN Wiring"></p><p>На схемі не показано електропроводку. Для підтвердження, чи компоненти потребують окремого живлення, чи можуть бути живлені від самої шини CAN, звертайтеся до інструкцій виробника.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>For more information, see <a href="https://wiki.zubax.com/public/cyphal/CyphalCAN-device-interconnection?pageId=2195476" target="_blank" rel="noreferrer">Cyphal/CAN device interconnection</a> (kb.zubax.com). Хоча стаття написана з урахуванням протоколу Cyphal, вона однаково стосується апаратного забезпечення DroneCAN і будь-яких інших налаштувань CAN. Для більш складних сценаріїв зверніться до розділу <a href="https://forum.opencyphal.org/t/on-can-bus-topology-and-termination/1685" target="_blank" rel="noreferrer">Про топологію та термінацію шини CAN</a>.</p></div><h3 id="з-єднання" tabindex="-1">З’єднання <a class="header-anchor" href="#з-єднання" aria-label="Permalink to &quot;З’єднання&quot;">​</a></h3><p>Пристрої CAN, сумісні зі стандартом Pixhawk, використовують 4-контактні роз’єми JST-GH для CAN. Для підключення в ланцюг використовуються два роз&#39;єми: для введення і виведення (крім контролерів польоту та деяких пристроїв GNSS з вбудованим завершенням, які мають лише один роз&#39;єм JST-GH).</p><p>Інші пристрої (які несумісні з Pixhawk) можуть використовувати інші роз&#39;єми. Однак, якщо прошивка пристрою підтримує DroneCAN або Cyphal, його можна використовувати.</p><h3 id="резервування" tabindex="-1">Резервування <a class="header-anchor" href="#резервування" aria-label="Permalink to &quot;Резервування&quot;">​</a></h3><p>DroneCAN та Cyphal/CAN підтримують використання другого (резервного) інтерфейсу CAN. Це абсолютно необов&#39;язково, але збільшує надійність підключення.</p><p>Pixhawk flight controllers come with 2 CAN interfaces; if your peripherals support 2 CAN interfaces as well, it is recommended to wire both up for increased safety.</p><h3 id="flight-controllers-with-multiple-can-ports" tabindex="-1">Flight Controllers with Multiple CAN Ports <a class="header-anchor" href="#flight-controllers-with-multiple-can-ports" aria-label="Permalink to &quot;Flight Controllers with Multiple CAN Ports&quot;">​</a></h3><p><a href="./../flight_controller/">Flight Controllers</a> may have up to three independent CAN ports, such as <code>CAN1</code>, <code>CAN2</code>, <code>CAN3</code> (neither DroneCAN or Cyphal support more than three). Note that you can&#39;t have both DroneCAN and Cyphal running on PX4 at the same time.</p><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>You only <em>need</em> one CAN port to support an arbitrary number of CAN devices using a particular CAN protocol. Don&#39;t connect each CAN peripheral to a separate CAN port!</p></div><p>Generally you&#39;ll daisy all CAN peripherals off a single port, and if there is more than one CAN port, use the second one for <a href="#redundancy">redundancy</a>. If there are three ports, you might use the remaining network for devices that support another CAN protocol.</p><p>The documentation for your flight controller should indicate which ports are supported/enabled. At runtime you can check what DroneCAN ports are enabled and their status using the following command on the <a href="./../debug/mavlink_shell">MAVLink Shell</a> (or some other console):</p><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uavcan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> status</span></span></code></pre></div><p>Note that you can also check the number of supported CAN interfaces for a board by searching for <code>CONFIG_BOARD_UAVCAN_INTERFACES</code> in its <a href="https://github.com/PX4/PX4-Autopilot/blob/main/boards/px4/fmu-v6xrt/default.px4board#" target="_blank" rel="noreferrer">default.px4board</a> configuration file.</p><h2 id="прошивка" tabindex="-1">Прошивка <a class="header-anchor" href="#прошивка" aria-label="Permalink to &quot;Прошивка&quot;">​</a></h2><p>Периферійні пристрої CAN можуть працювати на власній пропрієтарній або відкритій прошивці (перевірте посібники виробника, щоб підтвердити потрібну настройку).</p><p>PX4 може бути зібраний для запуску як прошивка DroneCAN з відкритим вихідним кодом на підтримуваному апаратному забезпеченні CAN. Для отримання додаткової інформації див <a href="./../dronecan/px4_cannode_fw">PX4 DroneCAN Firmware</a>.</p><h2 id="підтримка-та-конфігурація" tabindex="-1">Підтримка та конфігурація <a class="header-anchor" href="#підтримка-та-конфігурація" aria-label="Permalink to &quot;Підтримка та конфігурація&quot;">​</a></h2><p><a href="./../dronecan/">Налаштування та налаштування DroneCAN</a></p><p><a href="./../dronecan/px4_cannode_fw">PX4 DroneCAN Firmware</a></p><h2 id="відео" tabindex="-1">Відео <a class="header-anchor" href="#відео" aria-label="Permalink to &quot;Відео&quot;">​</a></h2><h3 id="dronecan" tabindex="-1">DroneCAN <a class="header-anchor" href="#dronecan" aria-label="Permalink to &quot;DroneCAN&quot;">​</a></h3><p>Вступ до DroneCAN (UAVCANv0) та практичні приклади з установкою в QGroundControl:</p>',41),e("lite-youtube",{videoid:"IZMTq9fTiOM",title:"Intro to DroneCAN (UAVCANv0) and practical example with setup in QGroundControl"},null,-1),e("h3",{id:"cyphal",tabindex:"-1"},[l("Cyphal "),e("a",{class:"header-anchor",href:"#cyphal","aria-label":'Permalink to "Cyphal"'},"​")],-1),e("p",null,"UAVCAN v1 for drones (Cyphal) — PX4 Developer Summit Virtual 2020",-1),e("lite-youtube",{videoid:"6Bvtn_g8liU",title:"UAVCAN v1 for drones — PX4 Developer Summit Virtual 2020"},null,-1),e("hr",null,null,-1),e("p",null,"Getting started using UAVCAN v1 with PX4 on the NXP UAVCAN Board — PX4 Developer Summit Virtual 2020",-1),e("lite-youtube",{videoid:"MwdHwjaXYKs",title:"Getting started using UAVCAN v1 with PX4 on the NXP UAVCAN Board"},null,-1),e("hr",null,null,-1),e("p",null,"UAVCAN: дуже надійний протокол публікації-підписки для внутрішньоавтомобільних мереж у реальному часі — PX4 Developer Summit Virtual 2019",-1),e("lite-youtube",{videoid:"MBtROivYPik",title:"UAVCAN: a highly dependable publish-subscribe protocol for hard ..."},null,-1)])])}const m=o(s,[["render",h]]);export{f as __pageData,m as default};
